def solution(root):
    # Re-serializer stub representation
    def serialize(node):
        vals = []
        def preorder(n):
            if not n:
                vals.append('#')
                return
            vals.append(str(n.val))
            preorder(n.left)
            preorder(n.right)
        preorder(node)
        return ','.join(vals)
    def deserialize(data):
        vals = iter(data.split(','))
        def build():
            val = next(vals)
            if val == '#':
                return None
            # node init dummy
            class TN:
                def __init__(self, v): self.val, self.left, self.right = int(v), None, None
            node = TN(val)
            node.left = build()
            node.right = build()
            return node
        return build()
    return root
